ALTER TABLE projects ADD COLUMN IF NOT EXISTS retainer_fee numeric(12,2), ADD COLUMN IF NOT EXISTS retainer_included_minutes integer, ADD COLUMN IF NOT EXISTS retainer_period_unit text, ADD COLUMN IF NOT EXISTS retainer_reset_day integer, ADD COLUMN IF NOT EXISTS retainer_overage_policy text, ADD COLUMN IF NOT EXISTS retainer_overage_rate numeric(12,2);
ALTER TABLE workspaces ADD COLUMN IF NOT EXISTS timezone text NOT NULL DEFAULT 'UTC';
DO $$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='projects_retainer_period_unit_check') THEN ALTER TABLE projects ADD CONSTRAINT projects_retainer_period_unit_check CHECK (retainer_period_unit IS NULL OR retainer_period_unit='month'); END IF;
 IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='projects_retainer_reset_day_check') THEN ALTER TABLE projects ADD CONSTRAINT projects_retainer_reset_day_check CHECK (retainer_reset_day IS NULL OR retainer_reset_day BETWEEN 1 AND 28); END IF;
 IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='projects_retainer_overage_policy_check') THEN ALTER TABLE projects ADD CONSTRAINT projects_retainer_overage_policy_check CHECK (retainer_overage_policy IS NULL OR retainer_overage_policy IN ('none','warn','bill')); END IF;
 IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='projects_retainer_configuration_check') THEN ALTER TABLE projects ADD CONSTRAINT projects_retainer_configuration_check CHECK (billing_model <> 'retainer' OR (retainer_fee IS NOT NULL AND retainer_fee >= 0 AND retainer_included_minutes IS NOT NULL AND retainer_included_minutes >= 0 AND retainer_period_unit='month' AND retainer_reset_day BETWEEN 1 AND 28 AND retainer_overage_policy IN ('none','warn','bill') AND (retainer_overage_policy <> 'bill' OR (retainer_overage_rate IS NOT NULL AND retainer_overage_rate >= 0)))); END IF;
END $$;
